import{_ as s,c as n,o as a,a6 as l}from"./chunks/framework.CZHnDj0c.js";const M=JSON.parse('{"title":"一、工业相机从传感器到上位机的信号链流程图","description":"","frontmatter":{},"headers":[],"relativePath":"src/camera/cameraLink.md","filePath":"src/camera/cameraLink.md"}'),p={name:"src/camera/cameraLink.md"},i=l(`<h1 id="一、工业相机从传感器到上位机的信号链流程图" tabindex="-1">一、工业相机从传感器到上位机的信号链流程图 <a class="header-anchor" href="#一、工业相机从传感器到上位机的信号链流程图" aria-label="Permalink to &quot;一、工业相机从传感器到上位机的信号链流程图&quot;">​</a></h1><ol><li><p>Camera Link是由AIA（Automated Imaging Association）制定的工业相机接口标准，面向高速、低时延的图像传输，采用LVDS并行传输并定义了统一的物理连接器与线缆。标准包含Base/Medium/Full三档配置：Base使用4个数据通道，Medium使用8个，Full使用12个；在85 MHz像素时钟下，Base约2.0 Gbps、Medium约4.8 Gbps、Full约5.4 Gbps（约680 MB/s）。规范还包含一条双向串行通信通道用于相机参数配置与控制。Camera Link通常需配合帧采集卡（Frame Grabber）使用，典型线缆长度&lt; 10 m</p></li><li><p>Camera Link使用LVDS并行差分信号与专用线缆/连接器（如MDR‑26/SDR‑26），可实现高速、低时延的图像传输，并支持双向串行通信。</p></li></ol><hr><h2 id="📊-工业相机信号链流程图" tabindex="-1"><strong>📊 工业相机信号链流程图</strong> <a class="header-anchor" href="#📊-工业相机信号链流程图" aria-label="Permalink to &quot;**📊 工业相机信号链流程图**&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|      被测物体 (光照)        |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|  工业相机 — Image Sensor   |  ←【传感器】</span></span>
<span class="line"><span>|  (CCD / CMOS 感光阵列)      |</span></span>
<span class="line"><span>|  - 分辨率 (如 8K 线阵)       |</span></span>
<span class="line"><span>|  - 位深 (8/10/12/14bit)     |</span></span>
<span class="line"><span>|  - 全局/卷帘快门             |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|   传感器输出 RAW 数据       |  (可能是 Bayer / Mono)</span></span>
<span class="line"><span>|   → 送入机内 ISP 或直出     |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>          【ISP】(可选)</span></span>
<span class="line"><span>    - 去马赛克 / 3A / 色彩校正</span></span>
<span class="line"><span>    - Gamma / 锐化 / 去噪</span></span>
<span class="line"><span>    - 输出 YUV / RGB / RAW</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|      相机接口层            |</span></span>
<span class="line"><span>|  ┌─────────────────────┐  |</span></span>
<span class="line"><span>|  │ GigE Vision         │ → RJ45 / 网口（无需采集卡）|</span></span>
<span class="line"><span>|  │ USB3 Vision         │ → USB3（无需采集卡）  |</span></span>
<span class="line"><span>|  │ Camera Link         │ → LVDS 差分信号【差分信号】|</span></span>
<span class="line"><span>|  │ CoaXPress (CXP)     │ → 同轴差分信号【差分信号】|</span></span>
<span class="line"><span>|  └─────────────────────┘  |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>   【是否需要采集卡？】</span></span>
<span class="line"><span>   ✅ Camera Link / CXP → 必须 PCIe 采集卡</span></span>
<span class="line"><span>   ❌ GigE / USB3 → 网卡/USB控制器即采集功能</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|   图像采集卡 (Frame Grabber)|</span></span>
<span class="line"><span>|  - PCIe 高速总线传输        |</span></span>
<span class="line"><span>|  - DMA 零拷贝搬运           |</span></span>
<span class="line"><span>|  - 硬件触发 &amp; 同步 I/O      |</span></span>
<span class="line"><span>|  - 缓存 &amp; FPGA 预处理       |</span></span>
<span class="line"><span>|  - PoCL / PoCXP 供电        |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>            ↓</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span>|   上位机 (PC / 工控机)      |</span></span>
<span class="line"><span>|  - CPU / GPU / FPGA 处理    |</span></span>
<span class="line"><span>|  - 算法 (检测/测量/识别)    |</span></span>
<span class="line"><span>|  - 显示 / 存储 / 通信       |</span></span>
<span class="line"><span>+---------------------------+</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--- 线阵相机特有参数 ---</span></span>
<span class="line"><span>行频 (Line Rate)：每秒采集的行数 [Hz/kHz]  ←【行频】</span></span>
<span class="line"><span>最高行频：相机 &amp; 接口能保证不丢数据的最大行频 ←【最高行频】</span></span></code></pre></div><hr><h3 id="🔍-各模块作用与关联说明" tabindex="-1"><strong>🔍 各模块作用与关联说明</strong> <a class="header-anchor" href="#🔍-各模块作用与关联说明" aria-label="Permalink to &quot;**🔍 各模块作用与关联说明**&quot;">​</a></h3><ol><li><p><strong>传感器</strong></p><ul><li>将光信号转为电信号（RAW数据）。</li><li>决定分辨率、位深、快门类型、感光能力。</li></ul></li><li><p><strong>ISP（可选）</strong></p><ul><li>若在相机内完成：输出可直接使用的 RGB/YUV。</li><li>若直出 RAW：需在上位机/嵌入式平台完成 ISP。</li></ul></li><li><p><strong>差分信号</strong>（Camera Link / CXP）</p><ul><li>用 LVDS 或同轴差分传输高速数据，抗干扰强、适合短距离高带宽。</li><li>必须通过采集卡转成 PCIe 数据进主机。</li></ul></li><li><p><strong>行频 &amp; 最高行频</strong></p><ul><li>线阵相机每秒输出的行数。</li><li>最高行频受传感器读取速度、接口带宽、采集卡缓存限制。</li><li>选型时要保证<strong>需求行频 ≤ 最高行频</strong>。</li></ul></li><li><p><strong>采集卡</strong></p><ul><li>在 Camera Link / CXP 场景下必不可少。</li><li>提供高速 DMA、硬件触发、同步 I/O、PoCL/PoCXP 供电。</li><li>对 GigE/USB3 相机则不需要额外采集卡（网卡/USB控制器代替）。</li></ul></li><li><p><strong>上位机</strong></p><ul><li>运行视觉算法、显示与存储图像。</li><li>如果是 RAW 数据，这里还要跑 ISP 管线。</li></ul></li></ol><hr><h3 id="🎯-结合你之前的埃科采集卡与相机" tabindex="-1"><strong>🎯 结合你之前的埃科采集卡与相机</strong> <a class="header-anchor" href="#🎯-结合你之前的埃科采集卡与相机" aria-label="Permalink to &quot;**🎯 结合你之前的埃科采集卡与相机**&quot;">​</a></h3><ul><li><p>如果你的相机是 <strong>CXP 接口</strong>（如埃科 Vulcan-CXP 系列），那么流程中：</p><ul><li>相机 → 同轴差分信号 → 埃科采集卡 → PCIe → 上位机。</li><li>行频/最高行频要匹配采集卡的单通道带宽（CXP-6 ≈ 625 MB/s，CXP-12 ≈ 1250 MB/s）。</li><li>采集卡还负责触发同步、PoCXP 供电、多相机拓扑管理。</li></ul></li><li><p>如果是 <strong>GigE 相机</strong>：流程中相机 → RJ45 → 网卡 → 上位机，无需埃科采集卡，行频概念变为帧频。</p></li></ul><hr><p>这样一张图就把<strong>传感器 → ISP → 接口（差分信号） → 采集卡 → 上位机</strong>全串起来了，并且标出了<strong>行频 / 最高行频</strong>的位置，方便你在选型与调试时对照检查。</p><hr><h1 id="二、camera-link-的-base-与-medium-配置" tabindex="-1">二、Camera Link 的 Base 与 Medium 配置 <a class="header-anchor" href="#二、camera-link-的-base-与-medium-配置" aria-label="Permalink to &quot;二、Camera Link 的 Base 与 Medium 配置&quot;">​</a></h1><p><strong>核心概念与带宽</strong></p><ul><li><strong>Base</strong>：单线缆（<strong>1×MDR</strong>），每帧携带<strong>24位</strong>图像数据，最大像素时钟<strong>85 MHz</strong>，理论吞吐约<strong>255 MB/s</strong>。适合中低分辨率或中帧率应用。</li><li><strong>Medium</strong>：双线缆（<strong>2×MDR</strong>），每帧携带<strong>48位</strong>图像数据，最大像素时钟<strong>85 MHz</strong>，理论吞吐约<strong>510 MB/s</strong>。适合更高分辨率/更高行频/更高帧率场景。</li><li>计算方式：<strong>吞吐量（MB/s）</strong>= 像素时钟（MHz）× 数据位数 ÷ 8。上述数值为标准定义的理论上限，实际可用有效带宽会因协议开销、同步与采集卡实现而略低。</li></ul><p><strong>端口与芯片构成</strong></p><ul><li><strong>Base</strong>：占用<strong>A/B/C</strong>三个端口，使用<strong>1</strong>个 Channel Link 芯片，提供<strong>24位</strong>视频数据通道。</li><li><strong>Medium</strong>：在 Base 基础上再加<strong>1</strong>个 Channel Link 基本单元，使用<strong>A–F</strong>共六个端口，提供<strong>48位</strong>视频数据通道。</li><li>说明：两种配置在连接器与线缆规范上保持统一，差异主要体现在占用的端口数量与并行数据位宽。</li></ul><p><strong>线缆与采集卡要求</strong></p><ul><li><strong>Base</strong>：<strong>1 根 MDR 电缆</strong>，需支持 Base 的<strong>帧采集卡</strong>（Frame Grabber）。</li><li><strong>Medium</strong>：<strong>2 根 MDR 电缆</strong>，需支持 Medium/Full 的采集卡（通常同一块卡可覆盖 Base/Medium/Full）。</li><li>采集卡需与相机的配置匹配（端口数、位宽与时钟能力）才能满速工作。</li></ul><p><strong>选型与带宽速算</strong></p><ul><li>速算公式：所需配置 ≥ 图像数据率（MB/s）。其中<strong>图像数据率</strong> = 分辨率（像素/行 × 行/帧）× 位深（bit）÷ 8 ÷ 帧率（fps）。</li><li>示例： <ul><li><strong>4K（4096×2160）@ 12bit @ 60fps</strong> → 数据率 ≈ <strong>756 MB/s</strong>，需 <strong>Medium/Full</strong>。</li><li><strong>2K（2048×1080）@ 8bit @ 120fps</strong> → 数据率 ≈ <strong>317 MB/s</strong>，<strong>Base</strong>在理论上限附近，建议用 <strong>Medium</strong> 留余量。</li></ul></li><li>工程建议：在理论值基础上预留**20–30%**带宽余量，以应对协议开销、触发抖动与采集卡缓存调度。</li></ul><h1 id="三、-camera-link-的-base、medium、full-含义" tabindex="-1">三、 Camera Link 的 Base、Medium、Full 含义 <a class="header-anchor" href="#三、-camera-link-的-base、medium、full-含义" aria-label="Permalink to &quot;三、 Camera Link 的 Base、Medium、Full 含义&quot;">​</a></h1><ul><li><strong>Base、Medium、Full</strong>是 <strong>Camera Link</strong> 标准的三种接口配置，用来规定一帧图像在<strong>LVDS差分通道</strong>上的并行数据宽度与端口占用。它们使用统一的物理接插件（如 <strong>MDR‑26/SDR‑26</strong>），但并行通道数与吞吐能力不同： <ul><li><strong>Base</strong>：占用 <strong>A/B/C 3 个端口</strong>，由 <strong>1 个 Channel Link 芯片</strong>传输，典型有效带宽约 <strong>255 MB/s（≈2.04 Gbps）@ 85 MHz</strong>。</li><li><strong>Medium</strong>：占用 <strong>A–F 6 个端口</strong>，由 <strong>2 个 Channel Link 芯片</strong>传输，典型有效带宽约 <strong>510 MB/s（≈4.08 Gbps）@ 85 MHz</strong>。</li><li><strong>Full</strong>：占用 <strong>A–H 8 个端口</strong>，由 <strong>3 个 Channel Link 芯片</strong>传输，典型有效带宽约 <strong>680 MB/s（≈5.44 Gbps）@ 85 MHz</strong>。<br> 这些数值来自标准定义与典型实现，反映了“配置越高，可并行携带的图像数据越多”的本质。</li></ul></li></ul><p><strong>与采集卡输出速率的关系</strong></p><ul><li>这三个配置并不是“采集卡输出图像的速率”，而是相机/接口在硬件层面提供的<strong>最大可传输带宽上限</strong>。你的系统“实际输出到内存的速率”取决于： <ol><li>相机的<strong>分辨率 × 位深 × 帧率/行频</strong>（图像数据率）；</li><li>所选 <strong>Base/Medium/Full</strong> 是否足以承载该数据率（需留有余量）；</li><li>采集卡的<strong>PCIe 总线带宽</strong>与驱动/DMA能力；</li><li>触发、同步、图像格式转换等带来的开销。<br> 举例：若相机输出为 <strong>4096×2160，12bit，60 fps</strong>，图像数据率 ≈ 4096×2160×12÷8×60 ≈ <strong>756 MB/s</strong>，已超过 **Base（≈255 MB/s）**与 <strong>Medium（≈510 MB/s）</strong>，需选择 **Full（≈680 MB/s）**并留有余量，且采集卡与主机总线也要能跟上。</li></ol></li></ul><p><strong>如何判断选 Base、Medium 还是 Full</strong></p><ul><li>速算公式：所需带宽（MB/s） ≥ 分辨率（像素/行 × 行/帧）× 位深（bit）÷ 8 ÷ 帧率（或行频）。</li><li>选型规则：让“相机所需带宽” ≤ “所选配置的标称带宽”，并建议<strong>预留 20–30% 余量</strong>以应对协议开销、触发抖动与系统调度。</li><li>工程经验： <ul><li>中低分辨率/中帧率 → 选 <strong>Base</strong>；</li><li>高分辨率或高帧率 → 选 <strong>Medium/Full</strong>；</li><li>线阵相机按“行频 × 每行字节数”来算，更直观判断是否超带宽。</li></ul></li></ul><p><strong>补充 80‑bit 与 Deca</strong></p><ul><li>在 **Full（8 端口）**基础上，部分设备还支持 **80‑bit（又称 Deca）**扩展，通过增加少量控制/数据位宽进一步提升吞吐，工程上常见标称可达约 <strong>6.8 Gbps（≈850 MB/s）</strong>。是否可用取决于相机与采集卡是否同时支持该模式。</li></ul>`,31),r=[i];function t(o,e,g,c,u,m){return a(),n("div",null,r)}const h=s(p,[["render",t]]);export{M as __pageData,h as default};
